/// Host parameter id of the on/off switch of OP1..OP6.
pub const OP_ON_IDS: [u32; 6] = [
    121, 221, 321, 421, 521, 621,
];

/// Host parameter id of byte `k` (0..=20) of operator `n` (1..=6).
pub const fn op_param_id(n: usize, k: usize) -> u32 {
    (100 * n + k) as u32
}

/// Host parameter id of voice byte 126..=144.
pub const fn voice_param_id(byte: usize) -> u32 {
    (1000 + byte - 126) as u32
}
